"""Named terminal rematch registrations, after the ignored system receipt.

The registration receipt is deliberately not bound. Its preceding NPC speech is
retained by CompanionDialogue_IsSystemReceipt, as verified by the parent task.
"""
ROWS = []
def add(key, labels, subject, lines):
    replies = [s.strip() for s in lines.split('|')]
    assert len(replies) == 11, (key, len(replies))
    ROWS.append(dict(key='route_registration_' + key, labels=labels.split(), subject=subject, replies=replies))

add('andres','Route105_Text_AndresRegister','Andres is surprised we want his contact despite his weak battling.',
'''soft_smile~Friendship doesn't require a qualifying score.|A contact can be worth keeping for more than battle performance.|He doesn't need to beat us to be worth knowing.|I'd like him to know the invitation isn't pity.|A good conversation matters as much as a difficult match.|An interesting acquaintance needn't arrive with an undefeated record.|My friendships would be sparse if competence were mandatory.|We could compare discoveries as well as battle results.|A name can matter without a victory attached.|He has more to offer than his least confident skill.|His surprise says he wasn't expecting someone to choose his company.''')
